INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 21, 'theory', 'Квиз: сети oVirt');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 21, 0, 'Что произойдёт с хостом, если обязательная (required) сеть кластера на нём не работает?', '["Хост продолжит работать без изменений", "Хост будет удалён из кластера", "Хост перейдёт в состояние NonOperational", "Хост будет автоматически перезагружен"]', 2, 'Обязательная сеть нужна всем хостам кластера. Если её нет, менеджер переводит хост в NonOperational, и машины с него переезжают. Необязательная сеть так не действует.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 21, 1, 'Какой режим бонда требует настроенной группы LACP на портах коммутатора?', '["802.3ad (режим 4)", "active-backup (режим 1)", "balance-tlb (режим 5)", "balance-alb (режим 6)"]', 0, 'Режим 4 договаривается с коммутатором по LACP, поэтому там нужна группа агрегации. Режимы 1, 5 и 6 обходятся без поддержки коммутатора.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 21, 2, 'Что делает VDSM, если после setupNetworks с проверкой связи менеджер не смог достучаться до хоста?', '["Оставляет новую конфигурацию", "Перезагружает хост", "Удаляет хост из кластера", "Возвращает прежнюю конфигурацию"]', 3, 'Проверка связи нужна как раз для этого: если после применения менеджер не достучался до хоста за таймаут, прежняя конфигурация возвращается.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 21, 3, 'Где задаются зеркалирование портов, сетевой фильтр и ограничение скорости виртуальной сетевой карты?', '["В свойствах виртуального диска", "В профиле vNIC", "В настройках кластера хранения", "В конфигурации libvirt на каждом хосте вручную"]', 1, 'Профиль vNIC живёт на уровне сети и хранит такие настройки; машина получает их, подключаясь к сети через профиль.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 21, 4, 'Какой туннельный протокол используют хосты для оверлейных сетей OVN в oVirt?', '["GRE поверх VLAN", "IPsec ESP", "Geneve", "Только транк VLAN без туннелей"]', 2, 'Хосты с ovn-controller соединяются туннелями Geneve поверх UDP. Туннель добавляет заголовки, поэтому MTU логической сети меньше физической.');
